function hpop(){ const H=S.heap; const top=H[0], last=H.pop(); if(H.length){ H[0]=last; const n=H.length; let c=0; for(;;){ const l=2*c+1,r=l+1; let m=c; if(l<n&&thr[H[l]]<thr[H[m]])m=l; if(r<n&&thr[H[r]]<thr[H[m]])m=r; if(m===c)break; const t=H[m];H[m]=H[c];H[c]=t; c=m; } } return top; }
