function markTrapped(){ const N=GW*GH; let reach=S.reach; if(!reach||reach.length!==N){ reach=S.reach=new Uint8Array(N); S.q=new Int32Array(N); } reach.fill(0); const q=S.q; let qt=0,qh=0;
  for(let x=0;x<GW;x++){ let i=x; if(inv[i]===0){reach[i]=1;q[qt++]=i;} i=(GH-1)*GW+x; if(inv[i]===0&&!reach[i]){reach[i]=1;q[qt++]=i;} }
  for(let y=0;y<GH;y++){ let i=y*GW; if(inv[i]===0&&!reach[i]){reach[i]=1;q[qt++]=i;} i=y*GW+GW-1; if(inv[i]===0&&!reach[i]){reach[i]=1;q[qt++]=i;} }
